import math

state = {
    'mode': 'UNPIN',
    'fwd_timer': 0.0,
    'fwd_dist': 0.0,
}

def control(obs):
    look_deg = -23.0
    dt = obs.get('dt', 0.1)
    status = obs.get('status', '')
    hitch_deg = obs.get('hitch_deg', 0.0)
    v_mps = obs.get('motion', {}).get('v_mps', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)

    # If in penalty hold, wait it out
    if hold_s > 0.05:
        return (0.0, 0.0, look_deg)

    views = obs.get('views', {})
    cam = views.get('camera')
    target_info = obs.get('target', {})
    bay_corners = cam.get('target_corners', []) if cam else []

    # Mode UNPIN: Pull forward to clear contact rail
    if state['mode'] == 'UNPIN':
        if v_mps > 0:
            state['fwd_dist'] += v_mps * dt
        state['fwd_timer'] += dt

        # Pull forward slightly right to pull trailer away from left rail
        if state['fwd_dist'] < 1.8 and state['fwd_timer'] < 5.0:
            return (-10.0, 1.0, look_deg)
        else:
            state['mode'] = 'REVERSING'

    # Reversing mode
    speed_mps = -0.65

    # Guide trailer towards bay / corridor
    target_b = -180.0
    if bay_corners:
        target_b = bay_corners[0][0]
    elif target_info.get('in_sight'):
        target_b = target_info.get('bearing_deg', -180.0)
    elif cam and cam.get('walls'):
        target_b = -135.0

    rel_target = (target_b - (-180) + 180) % 360 - 180
    desired_hitch = max(-22.0, min(22.0, rel_target * 0.5))

    hitch_err = hitch_deg - desired_hitch
    steer_deg = hitch_err * 2.2
    steer_deg = max(-34.0, min(34.0, steer_deg))

    return (steer_deg, speed_mps, look_deg)

