import math

state = {
    'fwd_timer': 0.0,
    'fwd_done': False
}

def control(obs):
    look_deg = -23.0
    dt = obs.get('dt', 0.1)
    hitch_deg = obs.get('hitch_deg', 0.0)
    motion = obs.get('motion', {})
    hold_s = motion.get('hold_s', 0.0)
    v_mps = motion.get('v_mps', 0.0)

    if hold_s > 0.05:
        return (0.0, 0.0, look_deg)

    views = obs.get('views', {})
    cam = views.get('camera')
    bay_corners = cam.get('target_corners', []) if cam else []

    # The trailer hit the rear-left rail because it swung too far left (hitch ~ +19°).
    # Pull forward further (around 2.5s) with wheels steered straight/slightly right (-5°)
    # to pull the trailer away from the corner and straighten the hitch angle to near 0°.
    if not state['fwd_done']:
        if v_mps > 0.1 or state['fwd_timer'] > 0:
            state['fwd_timer'] += dt
        if state['fwd_timer'] < 2.5:
            return (-5.0, 0.9, look_deg)
        else:
            state['fwd_done'] = True

    # Reversing phase: track the bend carefully
    speed_mps = -0.45

    # Notice camera walls show path curving towards -140° to -150°
    # We need the trailer to follow the curve into the bay without swinging wider than -10° to +5°
    desired_hitch = -8.0
    if bay_corners:
        tb = bay_corners[0][0]
        rel = (tb - (-180) + 180) % 360 - 180
        desired_hitch = max(-15.0, min(10.0, rel * 0.4))
    elif cam and cam.get('walls'):
        # Keep safe margin from left wall
        left_pts = [d for b, d in cam['walls'] if (b % 360) > 90 and (b % 360) < 180]
        if left_pts and min(left_pts) < 1.0:
            desired_hitch = -14.0
        else:
            desired_hitch = -8.0

    hitch_err = hitch_deg - desired_hitch
    steer_deg = hitch_err * 2.5
    steer_deg = max(-34.0, min(34.0, steer_deg))

    return (steer_deg, speed_mps, look_deg)

