import math

state = {
    'cleared': False,
    'fwd_timer': 0.0,
}

def control(obs):
    look_deg = -23.0
    dt = obs.get('dt', 0.1)
    hitch_deg = obs.get('hitch_deg', 0.0)
    motion = obs.get('motion', {})
    hold_s = motion.get('hold_s', 0.0)
    v_mps = motion.get('v_mps', 0.0)

    if hold_s > 0.05:
        return (0.0, 0.0, look_deg)

    views = obs.get('views', {})
    cam = views.get('camera')
    bay_corners = cam.get('target_corners', []) if cam else []

    # Rail touches: 7 / 8 max! ONE touch = failure.
    # The trailer's rear-left corner is touching at progress 16.7 m.
    # Step 1: pull forward straight for 1.3s to clear touch.
    if not state['cleared']:
        if v_mps > 0.05 or state['fwd_timer'] > 0:
            state['fwd_timer'] += dt
        if state['fwd_timer'] < 1.3:
            return (0.0, 0.7, look_deg)
        else:
            state['cleared'] = True

    # Step 2: Now we reverse carefully into the bay.
    # Bay is at -126°/7m.
    # Straight back for trailer is 180° / -180°.
    # Desired hitch must be negative so trailer rear swings right towards -126°.
    speed_mps = -0.4

    min_left_dist = 99.0
    if cam and cam.get('walls'):
        for b_deg, d_m in cam['walls']:
            lat = d_m * math.sin(math.radians(b_deg - (-hitch_deg)))
            if lat > 0 and lat < min_left_dist:
                min_left_dist = lat

    if bay_corners:
        b_bay = bay_corners[0][0]
        rel_bay = (b_bay - (-180) + 180) % 360 - 180
        desired_hitch = max(-22.0, min(-5.0, rel_bay * 0.4))
    else:
        desired_hitch = -15.0

    if min_left_dist < 0.75:
        desired_hitch = min(desired_hitch, -18.0)

    hitch_err = hitch_deg - desired_hitch
    steer_deg = hitch_err * 2.2
    steer_deg = max(-34.0, min(34.0, steer_deg))

    return (steer_deg, speed_mps, look_deg)

