import math

phase = 'unpin'

def control(obs):
    global phase
    status = obs.get('status', '')
    hitch = obs.get('hitch_deg', 0.0)
    steer = obs.get('steer_deg', 0.0)
    motion = obs.get('motion', {})
    hold = motion.get('hold_s', 0.0)
    v = motion.get('v_mps', 0.0)

    look_deg = 170.0

    # Unpinning logic
    if hold > 0.1 or status == 'PINNED':
        phase = 'unpin'
        return {'steer_deg': -10.0, 'speed_mps': -0.2, 'look_deg': look_deg}

    if phase == 'unpin':
        if status == 'REVERSING' and abs(v) > 0.05:
            phase = 'drive'
        else:
            return {'steer_deg': -5.0, 'speed_mps': -0.25, 'look_deg': look_deg}

    # Rail clearance checks
    views = obs.get('views', {})
    min_left = 999.0
    min_right = 999.0

    for vname, vdata in views.items():
        origin = vdata.get('origin', [0, 0])
        ox, oy = origin[0], origin[1]
        for pt in vdata.get('walls', []):
            b_rad = math.radians(pt[0])
            d = pt[1]
